ALTER TABLE laboratory_result_versions ADD COLUMN actor_id TEXT NOT NULL DEFAULT '';
ALTER TABLE diagnostic_report_versions ADD COLUMN actor_id TEXT NOT NULL DEFAULT '';
ALTER TABLE diagnostic_report_versions ADD COLUMN correction_reason TEXT NOT NULL DEFAULT '';
ALTER TABLE diagnostic_report_versions ADD COLUMN previous_version INTEGER;
CREATE TABLE laboratory_legacy_bridge(legacy_id TEXT PRIMARY KEY,canonical_result_id TEXT,state TEXT NOT NULL CHECK(state IN('MIGRATED','PENDING')),reason TEXT NOT NULL DEFAULT '',migrated_at INTEGER);
CREATE UNIQUE INDEX laboratory_orders_identity_patient ON laboratory_orders(id,patient_id);
CREATE UNIQUE INDEX laboratory_specimens_identity_patient ON laboratory_specimens(id,patient_id);
CREATE UNIQUE INDEX laboratory_results_identity_patient ON laboratory_results(id,patient_id);
CREATE UNIQUE INDEX diagnostic_reports_identity_patient ON diagnostic_reports(id,patient_id);
CREATE UNIQUE INDEX laboratory_specialty_identity_patient ON laboratory_specialty_records(id,patient_id);
CREATE TRIGGER laboratory_specimen_owner_insert BEFORE INSERT ON laboratory_specimens WHEN NOT EXISTS(SELECT 1 FROM laboratory_orders o WHERE o.id=NEW.order_id AND o.patient_id=NEW.patient_id) BEGIN SELECT RAISE(ABORT,'LAB_ORDER_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_specimen_owner_update BEFORE UPDATE OF order_id,patient_id ON laboratory_specimens WHEN NOT EXISTS(SELECT 1 FROM laboratory_orders o WHERE o.id=NEW.order_id AND o.patient_id=NEW.patient_id) BEGIN SELECT RAISE(ABORT,'LAB_ORDER_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_accession_owner_insert BEFORE INSERT ON laboratory_accessions WHEN NOT EXISTS(SELECT 1 FROM laboratory_orders o JOIN laboratory_specimens s ON s.order_id=o.id AND s.patient_id=o.patient_id WHERE o.id=NEW.order_id AND o.patient_id=NEW.patient_id AND s.id=NEW.specimen_id) BEGIN SELECT RAISE(ABORT,'LAB_ACCESSION_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_accession_owner_update BEFORE UPDATE OF order_id,specimen_id,patient_id ON laboratory_accessions WHEN NOT EXISTS(SELECT 1 FROM laboratory_orders o JOIN laboratory_specimens s ON s.order_id=o.id AND s.patient_id=o.patient_id WHERE o.id=NEW.order_id AND o.patient_id=NEW.patient_id AND s.id=NEW.specimen_id) BEGIN SELECT RAISE(ABORT,'LAB_ACCESSION_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_result_owner_insert BEFORE INSERT ON laboratory_results WHEN (NEW.order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM laboratory_orders o WHERE o.id=NEW.order_id AND o.patient_id=NEW.patient_id)) OR (NEW.specimen_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM laboratory_specimens s WHERE s.id=NEW.specimen_id AND s.patient_id=NEW.patient_id AND (NEW.order_id IS NULL OR s.order_id=NEW.order_id))) BEGIN SELECT RAISE(ABORT,'LAB_RESULT_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_result_owner_update BEFORE UPDATE OF order_id,specimen_id,patient_id ON laboratory_results WHEN (NEW.order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM laboratory_orders o WHERE o.id=NEW.order_id AND o.patient_id=NEW.patient_id)) OR (NEW.specimen_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM laboratory_specimens s WHERE s.id=NEW.specimen_id AND s.patient_id=NEW.patient_id AND (NEW.order_id IS NULL OR s.order_id=NEW.order_id))) BEGIN SELECT RAISE(ABORT,'LAB_RESULT_PATIENT_MISMATCH'); END;
CREATE TRIGGER diagnostic_report_order_owner_insert BEFORE INSERT ON diagnostic_reports WHEN NEW.order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM laboratory_orders o WHERE o.id=NEW.order_id AND o.patient_id=NEW.patient_id) BEGIN SELECT RAISE(ABORT,'DIAGNOSTIC_REPORT_PATIENT_MISMATCH'); END;
CREATE TRIGGER diagnostic_report_order_owner_update BEFORE UPDATE OF order_id,patient_id,provider_id ON diagnostic_reports WHEN NEW.order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM laboratory_orders o WHERE o.id=NEW.order_id AND o.patient_id=NEW.patient_id) BEGIN SELECT RAISE(ABORT,'DIAGNOSTIC_REPORT_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_specialty_specimen_owner_insert BEFORE INSERT ON laboratory_specialty_records WHEN NEW.specimen_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM laboratory_specimens s WHERE s.id=NEW.specimen_id AND s.patient_id=NEW.patient_id) BEGIN SELECT RAISE(ABORT,'LAB_SPECIALTY_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_specialty_specimen_owner_update BEFORE UPDATE OF specimen_id,patient_id ON laboratory_specialty_records WHEN NEW.specimen_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM laboratory_specimens s WHERE s.id=NEW.specimen_id AND s.patient_id=NEW.patient_id) BEGIN SELECT RAISE(ABORT,'LAB_SPECIALTY_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_result_attachment_owner_insert BEFORE INSERT ON laboratory_result_attachments WHEN NOT EXISTS(SELECT 1 FROM laboratory_results r JOIN documents d ON d.patient_id=r.patient_id WHERE r.id=NEW.result_id AND d.id=NEW.document_id) BEGIN SELECT RAISE(ABORT,'LAB_ATTACHMENT_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_result_attachment_version_insert BEFORE INSERT ON laboratory_result_attachments WHEN NOT EXISTS(SELECT 1 FROM laboratory_result_versions v WHERE v.result_id=NEW.result_id AND v.version=NEW.result_version) BEGIN SELECT RAISE(ABORT,'LAB_RESULT_VERSION_NOT_FOUND'); END;
CREATE TRIGGER laboratory_result_attachment_version_update BEFORE UPDATE OF result_id,result_version ON laboratory_result_attachments WHEN NOT EXISTS(SELECT 1 FROM laboratory_result_versions v WHERE v.result_id=NEW.result_id AND v.version=NEW.result_version) BEGIN SELECT RAISE(ABORT,'LAB_RESULT_VERSION_NOT_FOUND'); END;
CREATE TRIGGER laboratory_specialty_attachment_owner_insert BEFORE INSERT ON laboratory_specialty_attachments WHEN NOT EXISTS(SELECT 1 FROM laboratory_specialty_records r JOIN documents d ON d.patient_id=r.patient_id WHERE r.id=NEW.record_id AND d.id=NEW.document_id) BEGIN SELECT RAISE(ABORT,'LAB_SPECIALTY_ATTACHMENT_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_specialty_attachment_version_insert BEFORE INSERT ON laboratory_specialty_attachments WHEN NOT EXISTS(SELECT 1 FROM laboratory_specialty_versions v WHERE v.record_id=NEW.record_id AND v.version=NEW.version) BEGIN SELECT RAISE(ABORT,'LAB_SPECIALTY_VERSION_NOT_FOUND'); END;
CREATE TRIGGER laboratory_critical_notification_owner_insert BEFORE INSERT ON laboratory_critical_notifications WHEN NOT EXISTS(SELECT 1 FROM laboratory_results r WHERE r.id=NEW.result_id AND r.patient_id=NEW.patient_id) OR NOT EXISTS(SELECT 1 FROM laboratory_result_versions v WHERE v.result_id=NEW.result_id AND v.version=NEW.result_version) BEGIN SELECT RAISE(ABORT,'LAB_NOTIFICATION_PATIENT_MISMATCH'); END;
CREATE TRIGGER laboratory_result_identity_immutable BEFORE UPDATE OF patient_id,order_id,specimen_id,test_id,source_system,external_result_id ON laboratory_results WHEN NEW.patient_id IS NOT OLD.patient_id OR NEW.order_id IS NOT OLD.order_id OR NEW.specimen_id IS NOT OLD.specimen_id OR NEW.test_id IS NOT OLD.test_id OR NEW.source_system IS NOT OLD.source_system OR NEW.external_result_id IS NOT OLD.external_result_id BEGIN SELECT RAISE(ABORT,'immutable laboratory result identity'); END;
CREATE TRIGGER diagnostic_report_identity_immutable BEFORE UPDATE OF patient_id,order_id,provider_id ON diagnostic_reports WHEN NEW.patient_id IS NOT OLD.patient_id OR NEW.order_id IS NOT OLD.order_id OR NEW.provider_id IS NOT OLD.provider_id BEGIN SELECT RAISE(ABORT,'immutable diagnostic report identity'); END;
CREATE TRIGGER laboratory_specialty_identity_immutable BEFORE UPDATE OF patient_id,domain,specimen_id,source_system,external_record_id ON laboratory_specialty_records WHEN NEW.patient_id IS NOT OLD.patient_id OR NEW.domain IS NOT OLD.domain OR NEW.specimen_id IS NOT OLD.specimen_id OR NEW.source_system IS NOT OLD.source_system OR NEW.external_record_id IS NOT OLD.external_record_id BEGIN SELECT RAISE(ABORT,'immutable laboratory specialty identity'); END;
